# inspect components and shapes for d1
h,w=len(d1),len(d1[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if d1[r][c]!=2 or (r,c) in seen: continue
  st=[(r,c)];seen.add((r,c)); co=[]
  while st:
   x,y=st.pop();co.append((x,y))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<h and 0<=b<w and d1[a][b]==2 and (a,b) not in seen:seen.add((a,b));st.append((a,b))
  comps.append(sorted(co))
print(comps)
print([len(x) for x in comps])
